from mcp.server.fastmcp import FastMCP
from openpyxl import load_workbook
from pathlib import Path

mcp = FastMCP("excel")
ALLOWED = Path("/data/spreadsheets").resolve()   # AG-07 scoping
MAX_CELLS = 5_000

def _wb(name: str):
    p = (ALLOWED / name).resolve()
    if not str(p).startswith(str(ALLOWED)):
        raise ValueError(f"'{name}' outside the allowed folder")
    return load_workbook(p, data_only=False)   # formulas visible, documented

@mcp.tool()
def list_workbooks() -> list[dict]:
    """List .xlsx files with sheet names and dimensions.
    Always call this FIRST before reading anything.
    """
    return [{"file": f.name,
             "sheets": [{"name": ws.title, "max_row": ws.max_row,
                         "max_col": ws.max_column}
                        for ws in load_workbook(f, read_only=True)]}
            for f in ALLOWED.glob("*.xlsx")]

@mcp.tool()
def read_range(file: str, sheet: str, cell_range: str) -> dict:
    """Read a cell range (e.g. 'A1:F50') as rows of values.
    Use for structure discovery. For labeled data prefer read_table.
    Note: formulas return as formula strings, not computed values.
    Max 5,000 cells per call — read in chunks for big sheets.
    """
    ws = _wb(file)[sheet]
    rows = [[c.value for c in row] for row in ws[cell_range]]
    if sum(len(r) for r in rows) > MAX_CELLS:
        raise ValueError(f"range too large (max {MAX_CELLS} cells) — "
                         f"split into smaller ranges")
    return {"range": cell_range, "rows": rows}
